SELECT
    (SELECT COALESCE(SUM(COALESCE(sub.estimated_hours, 0)), 0)
     FROM sub_goal sub
              INNER JOIN stage_goal stage ON stage.id = sub.stage_id
     WHERE stage.user_id = #{userId}
       AND sub.user_id = #{userId}
       AND stage.create_time < #{cutoffExclusiveDate}
       AND (stage.completed_time IS NULL OR stage.completed_time >= #{startDate})
       AND stage.status != 4) AS total_estimated_hours,
    (SELECT COALESCE(SUM(checkin.spent_hours), 0)
     FROM goal_checkin checkin
              INNER JOIN stage_goal stage ON stage.id = checkin.stage_goal_id
     WHERE checkin.user_id = #{userId}
       AND stage.user_id = #{userId}
       AND checkin.is_deleted = 0
       AND checkin.checkin_date < #{startDate}
       AND stage.create_time < #{cutoffExclusiveDate}
       AND (stage.completed_time IS NULL OR stage.completed_time >= #{startDate})
       AND stage.status != 4) AS invested_before_period_hours,
    (SELECT COALESCE(SUM(COALESCE(sub.estimated_hours, 0)), 0)
     FROM sub_goal sub
              INNER JOIN stage_goal stage ON stage.id = sub.stage_id
     WHERE stage.user_id = #{userId}
       AND sub.user_id = #{userId}
       AND stage.completed_time >= #{startDate}
       AND stage.completed_time < #{cutoffExclusiveDate}) AS completed_estimated_hours,
    (SELECT COALESCE(SUM(checkin.spent_hours), 0)
     FROM goal_checkin checkin
              INNER JOIN stage_goal stage ON stage.id = checkin.stage_goal_id
     WHERE checkin.user_id = #{userId}
       AND stage.user_id = #{userId}
       AND checkin.is_deleted = 0
       AND stage.completed_time >= #{startDate}
       AND stage.completed_time < #{cutoffExclusiveDate}
       AND checkin.checkin_date <= DATE(stage.completed_time)) AS completed_actual_hours

SELECT checkin_date,
       COALESCE(SUM(spent_hours), 0) AS spent_hours
FROM goal_checkin
WHERE user_id = #{userId}
  AND is_deleted = 0
  AND checkin_date >= #{startDate}
  AND checkin_date <= #{cutoffDate}
GROUP BY checkin_date
ORDER BY checkin_date

SELECT stage.category,
       COALESCE(SUM(checkin.spent_hours), 0) AS spent_hours
FROM goal_checkin checkin
         INNER JOIN stage_goal stage ON stage.id = checkin.stage_goal_id
WHERE checkin.user_id = #{userId}
  AND stage.user_id = #{userId}
  AND checkin.is_deleted = 0
  AND checkin.checkin_date >= #{startDate}
  AND checkin.checkin_date <= #{cutoffDate}
GROUP BY stage.category
ORDER BY spent_hours DESC, stage.category ASC
